<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { Address } from '../types'
import { api } from '../services/api'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore();const addresses=ref<Address[]>([]);const loading=ref(true);const busy=ref(false);const error=ref('');const message=ref('')
const form=reactive({label:'Rumah',recipient_name:'',phone:'',address_line:'',city:'',province:'',postal_code:'',is_default:false})
async function load(){try{addresses.value=await api.get<Address[]>('/api/v1/addresses')}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat alamat'}finally{loading.value=false}}
async function submit(){busy.value=true;error.value='';message.value='';try{await api.post('/api/v1/addresses',form);Object.assign(form,{label:'Rumah',recipient_name:'',phone:'',address_line:'',city:'',province:'',postal_code:'',is_default:false});message.value='Alamat berhasil disimpan';await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal menyimpan alamat'}finally{busy.value=false}}
async function remove(id:string){if(!confirm('Hapus alamat ini?'))return;try{await api.delete('/api/v1/addresses/'+id);await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal menghapus alamat'}}
onMounted(load)
</script>
<template><section class="page-intro"><p class="eyebrow">AKUN NUSAMART</p><h1>Profil & alamat</h1><p>Kelola informasi akun dan alamat pengiriman.</p></section><div class="profile-layout"><section class="panel"><p class="eyebrow">INFORMASI AKUN</p><div class="profile-avatar">{{ auth.user?.full_name.slice(0,1).toUpperCase() }}</div><h2>{{ auth.user?.full_name }}</h2><p class="muted">{{ auth.user?.email }}</p><span class="category-pill">{{ auth.user?.role }}</span><div class="info-row"><span>Terdaftar</span><strong>{{ auth.user?.created_at?new Date(auth.user.created_at).toLocaleDateString('id-ID'):'—' }}</strong></div></section><section class="panel"><div class="section-heading"><div><p class="eyebrow">ALAMAT PENGIRIMAN</p><h2>Tambah alamat</h2></div></div><form class="form-grid" @submit.prevent="submit"><label class="field-label">Label<input v-model="form.label" required maxlength="50" placeholder="Rumah, Kantor…"/></label><label class="field-label">Nama penerima<input v-model="form.recipient_name" required minlength="2"/></label><label class="field-label">Nomor telepon<input v-model="form.phone" required minlength="8"/></label><label class="field-label span-two">Alamat lengkap<input v-model="form.address_line" required minlength="5" placeholder="Jalan, nomor rumah, RT/RW…"/></label><label class="field-label">Kota/Kabupaten<input v-model="form.city" required/></label><label class="field-label">Provinsi<input v-model="form.province" required/></label><label class="field-label">Kode pos<input v-model="form.postal_code" required minlength="4"/></label><label class="checkbox-label span-two"><input v-model="form.is_default" type="checkbox"/> Jadikan alamat utama</label><div class="span-two"><p v-if="error" class="error-banner">{{ error }}</p><p v-if="message" class="success-banner">{{ message }}</p><button class="button-primary" :disabled="busy">{{ busy?'Menyimpan…':'Simpan alamat' }}</button></div></form></section><section class="panel address-panel"><h2>Alamat tersimpan</h2><p v-if="loading" class="muted">Memuat alamat…</p><p v-else-if="!addresses.length" class="muted">Belum ada alamat. Tambahkan alamat di formulir.</p><article v-for="a in addresses" :key="a.id" class="saved-address"><div><div class="address-title"><strong>{{ a.label }}</strong><span v-if="a.is_default" class="category-pill">Utama</span></div><p><strong>{{ a.recipient_name }}</strong> · {{ a.phone }}</p><p>{{ a.address_line }}, {{ a.city }}, {{ a.province }} {{ a.postal_code }}</p></div><button class="link-button danger-text" @click="remove(a.id)">Hapus</button></article></section></div></template>
